#include <stdio.h>
void shift(int *a, int n)
{
  int i, t = a[0];
  for (i = 0; i < n - 1; i++)
    a[i] = a[i + 1];
  a[n - 1] = t;
}
int main(void)
{
  int b[5] = {1, 2, 3, 4, 5}, i;
  shift(b, 5);
  shift(b, 5);
  for (i = 0; i < 5; i++)
    printf("%d", b[i]);
  printf("\n");
  return 0;
}

