#include <stdio.h>
void count(char *s, int *letter, int *digit)
{
  *letter = *digit = 0;
  for (; *s != '\0'; s++) {
    if ((*s >= 'a' && *s <= 'z') ||
        (*s >= 'A' && *s <= 'Z'))
      (*letter)++;
    else if (*s >= '0' && *s <= '9')
      (*digit)++;
  }
}
int main(void)
{
  char s[82];
  int l, d;
  if (fgets(s, sizeof(s), stdin) == NULL)
    s[0] = '\0';
  count(s, &l, &d);
  printf("letters=%d digits=%d\n", l, d);
  return 0;
}

