int count(char *s, char *t)
{
  int n = 0;
  char *p, *q;
  for (; *s != '\0'; s++) {
    p = s;
    q = t;
    while (*q != '\0' && *p == *q) {
      p++;
      q++;
    }
    if (*q == '\0')
      n++;
  }
  return n;
}
int main(void)
{
  char s[81], t[81];
  scanf("%80s%80s", s, t);
  printf("%d\n", count(s, t));
  return 0;
}

