#include <stdio.h>
void mycopy(char *to, char *from)
{
  while (*from != '\0')
    *to++ = *from++;
  *to = '\0';
}
int main(void)
{
  char a[81], b[81];
  scanf("%s", a);
  mycopy(b, a);
  printf("%s\n", b);
  return 0;
}
